c=A.au(s2,A.a([A.at(A.a(["\ub300\uc218 > \uc218\uc5f4 > \uc218\ud559\uc801\uadc0\ub0a9\ubc95 > \uadc0\ub0a9\ubc95\uc758\uc6d0\ub9ac \uac1c\ub150 \ud559\uc2b5"],ai0),B.z,A.a([A.av(s3,B.q,A.a(["\uc218\ud559\uc801 \uadc0\ub0a9\ubc95\uc740 \uc790\uc5f0\uc218 $n$\uc5d0 \uad00\ud55c \uba85\uc81c $P(n)$\uc774 \ubaa8\ub4e0 \uc790\uc5f0\uc218\uc5d0 \ub300\ud558\uc5ec \uc131\ub9bd\ud568\uc744 \uc99d\uba85\ud558\ub294 \ub9e4\uc6b0 \uac15\ub825\ud55c \ub3c4\uad6c\uc785\ub2c8\ub2e4. \uc774 \uc6d0\ub9ac\ub294 \ub3c4\ubbf8\ub178\uac00 \uc904\uc9c0\uc5b4 \uc11c \uc788\ub294 \ubaa8\uc2b5\uacfc \uac19\uc2b5\ub2c8\ub2e4. \uccab \ubc88\uc9f8 \ub3c4\ubbf8\ub178\uac00 \uc4f0\ub7ec\uc9c0\uace0, \uc5b4\ub5a4 \ub3c4\ubbf8\ub178\uac00 \uc4f0\ub7ec\uc9c0\uba74 \ubc18\ub4dc\uc2dc \uadf8 \ub2e4\uc74c \ub3c4\ubbf8\ub178\ub3c4 \uc4f0\ub7ec\uc9c4\ub2e4\ub294 \uc0ac\uc2e4\uc744 \uc54c\uba74, \uacb0\uad6d \ubaa8\ub4e0 \ub3c4\ubbf8\ub178\uac00 \uc4f0\ub7ec\uc9c0\uac8c \ub41c\ub2e4\ub294 \ub17c\ub9ac\uc785\ub2c8\ub2e4.","\uc774\ub97c \uc218\ud559\uc801\uc73c\ub85c \uc5c4\ubc00\ud558\uac8c \uc815\uc758\ud558\uba74 \ub2e4\uc74c\uacfc \uac19\uc2b5\ub2c8\ub2e4. \uccab\uc9f8, $n=1$\uc77c \ub54c \uba85\uc81c $P(1)$\uc774 \ucc38\uc784\uc744 \ubcf4\uc785\ub2c8\ub2e4. \ub458\uc9f8, $n=k$\uc77c \ub54c \uba85\uc81c $P(k)$\uac00 \ucc38\uc774\ub77c\uace0 \uac00\uc815\ud558\uba74, $n=k+1$\uc77c \ub54c\ub3c4 \uba85\uc81c $P(k+1)$\uc774 \ucc38\uc774 \ub428\uc744 \ubcf4\uc785\ub2c8\ub2e4. \uc774 \ub450 \uac00\uc9c0 \uacfc\uc815\uc744 \ubaa8\ub450 \uc99d\uba85\ud558\uba74, \uc218\ud559\uc801 \uadc0\ub0a9\ubc95\uc758 \uc6d0\ub9ac\uc5d0 \uc758\ud574 \ubaa8\ub4e0 \uc790\uc5f0\uc218 $n$\uc5d0 \ub300\ud558\uc5ec \uba85\uc81c $P(n)$\uc774 \ucc38\uc774 \ub429\ub2c8\ub2e4.","\uc218\ud559\uc801 \uadc0\ub0a9\ubc95\uc758 \ud575\uc2ec \uacf5\uc2dd\uc740 \uc99d\uba85 \uacfc\uc815\uc758 \ub17c\ub9ac\uc801 \uc5f0\uacb0 \uace0\ub9ac\uc785\ub2c8\ub2e4. $n=k$\uc77c \ub54c\uc758 \uac00\uc815\uc744 $P(k)$\ub77c \ud558\uace0, \uc774\ub97c \uc774\uc6a9\ud558\uc5ec $P(k+1)$\uc744 \uc720\ub3c4\ud558\ub294 \uacfc\uc815\uc740 \uc8fc\ub85c \ub2e4\uc74c\uacfc \uac19\uc740 \ud615\ud0dc\ub97c \ub771\ub2c8\ub2e4. \ub9cc\uc57d $1+2+3+\\cdots+n = \\frac{n(n+1)}{2}$\uc774\ub77c\ub294 \uba85\uc81c\ub97c \uc99d\uba85\ud55c\ub2e4\uba74, $n=k$\uc77c \ub54c\uc758 \uc2dd\uc5d0 $(k+1)$\uc744 \uc591\ubcc0\uc5d0 \ub354\ud558\uc5ec $n=k+1$\uc77c \ub54c\uc758 \uc2dd\uc778 $\\frac{(k+1)(k+2)}{2}$\uac00 \ub428\uc744 \ud655\uc778\ud558\ub294 \ubc29\uc2dd\uc785\ub2c8\ub2e4.","\uc774\uc81c \uc608\uc81c\ub97c \ud1b5\ud574 \uc9c1\uc811 \uc801\uc6a9\ud574 \ubd05\uc2dc\ub2e4. '\ubaa8\ub4e0 \uc790\uc5f0\uc218 $n$\uc5d0 \ub300\ud558\uc5ec $1+3+5+\\cdots+(2n-1) = n^2$\uc774 \uc131\ub9bd\ud568\uc744 \uc218\ud559\uc801 \uadc0\ub0a9\ubc95\uc73c\ub85c \uc99d\uba85\ud558\uc2dc\uc624.'\ub77c\ub294 \ubb38\uc81c\ub97c \ud480\uc5b4\ubcf4\uaca0\uc2b5\ub2c8\ub2e4. \uba3c\uc800 $n=1$\uc77c \ub54c, \uc88c\ubcc0\uc740 $2(1)-1=1$\uc774\uace0 \uc6b0\ubcc0\uc740 $1^2=1$\uc774\ubbc0\ub85c $P(1)$\uc740 \ucc38\uc785\ub2c8\ub2e4.","\ub2e4\uc74c\uc73c\ub85c $n=k$\uc77c \ub54c, \uc989 $1+3+5+\\cdots+(2k-1) = k^2$\uc774 \uc131\ub9bd\ud55c\ub2e4\uace0 \uac00\uc815\ud569\ub2c8\ub2e4. \uc774\uc81c $n=k+1$\uc77c \ub54c\uc758 \uc2dd\uc744 \ud655\uc778\ud558\uae30 \uc704\ud574 \uc591\ubcc0\uc5d0 $(k+1)$\ubc88\uc9f8 \ud56d\uc778 $2(k+1)-1 = 2k+1$\uc744 \ub354\ud569\ub2c8\ub2e4. \uadf8\ub7ec\uba74 \uc88c\ubcc0\uc740 $1+3+5+\\cdots+(2k-1) + (2k+1)$\uc774 \ub418\uace0, \uc6b0\ubcc0\uc740 $k^2 + (2k+1)$\uc774 \ub429\ub2c8\ub2e4.","\uc6b0\ubcc0\uc744 \uc815\ub9ac\ud558\uba74 $k^2 + 2k + 1 = (k+1)^2$\uc774 \ub429\ub2c8\ub2e4. \uc774\ub294 $n=k+1$\uc77c \ub54c\uc758 \uba85\uc81c\uc640 \uc77c\uce58\ud569\ub2c8\ub2e4. \ub530\ub77c\uc11c $n=k$\uc77c \ub54c \uc131\ub9bd\ud55c\ub2e4\uace0 \uac00\uc815\ud558\uba74 $n=k+1$\uc77c \ub54c\ub3c4 \uc131\ub9bd\ud568\uc774 \uc99d\uba85\ub418\uc5c8\uc2b5\ub2c8\ub2e4. \uacb0\ub860\uc801\uc73c\ub85c \uc218\ud559\uc801 \uadc0\ub0a9\ubc95\uc5d0 \uc758\ud574 \uc8fc\uc5b4\uc9c4 \uba85\uc81c\ub294 \ubaa8\ub4e0 \uc790\uc5f0\uc218 $n$\uc5d0 \ub300\ud558\uc5ec \ud56d\uc0c1 \ucc38\uc785\ub2c8\ub2e4."],ai0),t6,B.n)],ai2),t6,B.n)],ai3),s3,s3,s3,"concept_\uadc0\ub0a9\ubc95\uc758\uc6d0\ub9ac",0,"","\ub300\uc218 > \uc218\uc5f4 > \uc218\ud559\uc801\uadc0\ub0a9\ubc95 > \uadc0\ub0a9\ubc95\uc758\uc6d0\ub9ac",c,t6,s3)
b=A.a(["\uacf5\ud1b5\uc218\ud5592","\ud568\uc218","\ud568\uc218\uc758\uc815\uc758","\uc815\uc758\uc5ed(\ud568\uc218)"],ai0)
b=A.au(s2,A.a([A.at(A.a(["\uacf5\ud1b5\uc218\ud5592 > \ud568\uc218 > \ud568\uc218\uc758\uc815\uc758 > \uc815\uc758\uc5ed(\ud568\uc218) \uac1c\ub150 \ud559\uc2b5"],ai0),B.z,A.a([A.av(s3,B.q,A.a(["\ud568\uc218\uc5d0\uc11c '\uc815\uc758\uc5ed'\uc774\ub780 \ud568\uc218\uac00 \uc785\ub825\uac12\uc744 \ubc1b\uc544\ub4e4\uc77c \uc218 \uc788\ub294 \ubaa8\ub4e0 \uac00\ub2a5\ud55c \uac12\ub4e4\uc758 \uc9d1\ud569\uc744 \uc758\ubbf8\ud569\ub2c8\ub2e4. \uc27d\uac8c \ub9d0\ud574, \ud568\uc218\ub77c\ub294 \uae30\uacc4\uc5d0 \ub123\uc744 \uc218 \uc788\ub294 '\uc7ac\ub8cc'\ub4e4\uc758 \ubaa8\uc784\uc774\ub77c\uace0 \uc0dd\uac01\ud558\uba74 \ub429\ub2c8\ub2e4. \ud568\uc218 $f: X \\rightarrow Y$\uc5d0\uc11c \uc9d1\ud569 $X$\uc758 \ubaa8\ub4e0 \uc6d0\uc18c\uac00 \uacf5\uc5ed $Y$\uc758 \uc6d0\uc18c\uc5d0 \ub2e8 \ud558\ub098\uc529 \ub300\uc751\ub420 \ub54c, \uc774 \uc9d1\ud569 $X$\ub97c \ud568\uc218 $f$\uc758 \uc815\uc758\uc5ed\uc774\ub77c\uace0 \ubd80\ub985\ub2c8\ub2e4.","\uc815\uc758\uc5ed\uc744 \uacb0\uc815\ud560 \ub54c \uac00\uc7a5 \uc911\uc694\ud55c \uac83\uc740 \ud568\uc218\uac00 \uc218\ud559\uc801\uc73c\ub85c '\uc815\uc758'\ub420 \uc218 \uc788\uc5b4\uc57c \ud55c\ub2e4\ub294 \uc810\uc785\ub2c8\ub2e4. \uc608\ub97c \ub4e4\uc5b4, \ubd84\uc218 \ud568\uc218\uc5d0\uc11c\ub294 \ubd84\ubaa8\uac00 0\uc774 \ub418\uba74 \uc548 \ub418\uace0, \uc81c\uacf1\uadfc(\ub8e8\ud2b8) \ud568\uc218\uc5d0\uc11c\ub294 \ub8e8\ud2b8 \uc548\uc758 \uac12\uc774 0\ubcf4\ub2e4 \ud06c\uac70\ub098 \uac19\uc544\uc57c \ud569\ub2c8\ub2e4. \ub9cc\uc57d \uc774\ub7ec\ud55c \uc870\uac74\uc744 \ub9cc\uc871\ud558\uc9c0 \uc54a\ub294 \uac12\uc744 \uc785\ub825\ud558\uba74 \ud568\uc218\uac12\uc774 \uc874\uc7ac\ud558\uc9c0 \uc54a\uac8c \ub418\ubbc0\ub85c, \uadf8\ub7ec\ud55c \uac12\ub4e4\uc740 \uc815\uc758\uc5ed\uc5d0\uc11c \uc81c\uc678\ud574\uc57c \ud569\ub2c8\ub2e4.","\uc815\uc758\uc5ed\uc744 \uc218\uc2dd\uc73c\ub85c \ud45c\ud604\ud560 \ub54c\ub294 \uc8fc\ub85c \uc870\uac74\uc81c\uc2dc\ubc95\uc744 \uc0ac\uc6a9\ud569\ub2c8\ub2e4. \uc608\ub97c \ub4e4\uc5b4, \ud568\uc218 $f(x) = \\frac{1}{x-2}$\uc758 \uc815\uc758\uc5ed\uc740 \ubd84\ubaa8\uac00 0\uc774 \ub418\ub294 $x=2$\ub97c \uc81c\uc678\ud55c \ubaa8\ub4e0 \uc2e4\uc218\uc774\ubbc0\ub85c, \ub2e4\uc74c\uacfc \uac19\uc774 \ub098\ud0c0\ub0c5\ub2c8\ub2e4. $$D = \\{x \\mid x \\in \\mathbb{R}, x \\neq 2\\}$$ \uc774\ucc98\ub7fc \uc815\uc758\uc5ed\uc740 \ud568\uc218\uc758 \uc131\uaca9\uc5d0 \ub530\ub77c \uc2e4\uc218 \uc804\uccb4\uc758 \uc9d1\ud569\uc774 \ub420 \uc218\ub3c4 \uc788\uace0, \ud2b9\uc815 \uad6c\uac04\uc774\ub098 \uc81c\ud55c\ub41c \ubc94\uc704\ub85c \uc8fc\uc5b4\uc9c8 \uc218\ub3c4 \uc788\uc2b5\ub2c8\ub2e4.","\uc774\uc81c \uad6c\uccb4\uc801\uc778 \uc608\uc81c\ub97c \ud1b5\ud574 \uc815\uc758\uc5ed\uc744 \uad6c\ud558\ub294 \ubc29\ubc95\uc744 \uc54c\uc544\ubd05\uc2dc\ub2e4. \ud568\uc218 $f(x) = \\sqrt{x-3}$\uc758 \uc815\uc758\uc5ed\uc744 \uad6c\ud574\ubcf4\uaca0\uc2b5\ub2c8\ub2e4. \uc81c\uacf1\uadfc \uc548\uc758 \uac12\uc740 \ud56d\uc0c1 0\ubcf4\ub2e4 \ud06c\uac70\ub098 \uac19\uc544\uc57c \ud558\ubbc0\ub85c, $x-3 \\geq 0$\uc774\ub77c\ub294 \ubd80\ub4f1\uc2dd\uc744 \uc138\uc6b8 \uc218 \uc788\uc2b5\ub2c8\ub2e4. \uc774\ub97c \ud480\uba74 $x \\geq 3$\uc774 \ub429\ub2c8\ub2e4.","\ub530\ub77c\uc11c \uc774 \ud568\uc218\uc758 \uc815\uc758\uc5ed\uc740 3\ubcf4\ub2e4 \ud06c\uac70\ub098 \uac19\uc740 \ubaa8\ub4e0 \uc2e4\uc218\uc758 \uc9d1\ud569\uc785\ub2c8\ub2e4. \uc774\ub97c \uc9d1\ud569 \uae30\ud638\ub85c \ub098\ud0c0\ub0b4\uba74 \ub2e4\uc74c\uacfc \uac19\uc2b5\ub2c8\ub2e4. $$D = \\{x \\mid x \\geq 3\\}$$ \uc774\uc640 \uac19\uc774 \ud568\uc218\uac00 \uc8fc\uc5b4\uc84c\uc744 \ub54c, \ud574\ub2f9 \ud568\uc218\uac00 \uc2e4\uc22b\uac12\uc744 \uac00\uc9c8 \uc218 \uc788\ub294 $x$\uc758 \ubc94\uc704\ub97c \ucc3e\ub294 \uac83\uc774 \uc815\uc758\uc5ed \uad6c\ud558\uae30\uc758 \ud575\uc2ec\uc785\ub2c8\ub2e4.","\ub9c8\uc9c0\ub9c9\uc73c\ub85c \ubd84\uc218 \ud568\uc218 $f(x) = \\frac{5}{x^2-4}$\uc758 \uc815\uc758\uc5ed\uc744 \uad6c\ud574\ubd05\uc2dc\ub2e4. \ubd84\ubaa8\uac00 0\uc774 \ub418\ub294 \uc9c0\uc810\uc5d0\uc11c\ub294 \ud568\uc218\uac12\uc774 \uc815\uc758\ub418\uc9c0 \uc54a\uc73c\ubbc0\ub85c, $x^2-4 = 0$\uc774 \ub418\ub294 $x$\uac12\uc744 \ucc3e\uc544\uc57c \ud569\ub2c8\ub2e4. $x^2 = 4$\ub97c \ud480\uba74 $x = 2$ \ub610\ub294 $x = -2$\uac00 \ub098\uc635\ub2c8\ub2e4. \ub530\ub77c\uc11c \uc774 \ub450 \uac12\uc744 \uc81c\uc678\ud55c \ubaa8\ub4e0 \uc2e4\uc218\uac00 \uc815\uc758\uc5ed\uc774 \ub418\uba70, \uc218\uc2dd\uc73c\ub85c\ub294 \ub2e4\uc74c\uacfc \uac19\uc774 \uc501\ub2c8\ub2e4. $$D = \\{x \\mid x \\neq 2, x \\neq -2\\}$$"],ai0),t7,B.n)],ai2),t7,B.n)],ai3),s3,s3,s3,"concept_\uc815\uc758\uc5ed(\ud568\uc218)",0,"","\uacf5\ud1b5\uc218\ud5592 > \ud568\uc218 > \ud568\uc218\uc758\uc815\uc758 > \uc815\uc758\uc5ed(\ud568\uc218)",b,t7,s3)
a=A.a(["\uacf5\ud1b5\uc218\ud5591","\uacbd\uc6b0\uc758\uc218","\uacf1\uc758\ubc95\uce59","\uc0ac\uac74\uc758\uacf1"],ai0)
a=A.au(s2,A.a([A.at(A.a(["\uacf5\ud1b5\uc218\ud5591 > \uacbd\uc6b0\uc758\uc218 > \uacf1\uc758\ubc95\uce59 > \uc0ac\uac74\uc758\uacf1 \uac1c\ub150 \ud559\uc2b5"],ai0),B.z,A.a([A.av(s3,B.q,A.a(['[   "\uacbd\uc6b0\uc758 \uc218\uc5d0\uc11c \'\uc0ac\uac74\uc758 \uacf1(\uacf1\uc758 \ubc95\uce59)\'\uc740 \ub450 \uc0ac\uac74\uc774 \uc5f0\ub2ec\uc544 \uc77c\uc5b4\ub098\uac70\ub098 \ub3d9\uc2dc\uc5d0 \uc77c\uc5b4\ub098\ub294 \uc0c1\ud669\uc744 \ub2e4\ub8f0 \ub54c \uc0ac\uc6a9\ud569\ub2c8\ub2e4. \uc0ac\uac74 A\uac00 \uc77c\uc5b4\ub098\ub294 \uacbd\uc6b0\uc758 \uc218\uac00 $m$\uac00\uc9c0\uc774\uace0, \uadf8 \uac01\uac01\uc758 \uacbd\uc6b0\uc5d0 \ub300\ud558\uc5ec \uc0ac\uac74 B\uac00 \uc77c\uc5b4\ub098\ub294 \uacbd\uc6b0\uc758 \uc218\uac00 $n$\uac00\uc9c0\uc77c \ub54c, \ub450 \uc0ac\uac74 A\uc640 B\uac00 \uc787\ub530\ub77c \uc77c\uc5b4\ub098\ub294 \uacbd\uc6b0\uc758 \uc218\ub294 $m \\\\times n$\uac00\uc9c0\uc785\ub2c8\ub2e4. \uc774\ub294 \ub2e8\uc21c\ud788 \ub450 \uc218\ub97c \uacf1\ud558\ub294 \uac83\uc774 \uc544\ub2c8\ub77c, \uccab \ubc88\uc9f8 \uc120\ud0dd\uc758 \ubaa8\ub4e0 \uac08\ub798\ub9c8\ub2e4 \ub450 \ubc88\uc9f8 \uc120\ud0dd\uc774 \uac01\uac01 \uc874\uc7ac\ud55c\ub2e4\ub294 \ub17c\ub9ac\uc801 \uad6c\uc870\ub97c \ubc14\ud0d5\uc73c\ub85c \ud569\ub2c8\ub2e4.",   "\uc774 \ubc95\uce59\uc774 \uc131\ub9bd\ud558\uae30 \uc704\ud574\uc11c\ub294 \ub450 \uc0ac\uac74\uc774 \uc11c\ub85c \uc601\ud5a5\uc744 \uc8fc\uc9c0 \uc54a\uc73c\uba74\uc11c \uc5f0\uc18d\uc801\uc73c\ub85c \ubc1c\uc0dd\ud574\uc57c \ud569\ub2c8\ub2e4. \uc608\ub97c \ub4e4\uc5b4, \uc0ac\uac74 A\ub97c \uc120\ud0dd\ud55c \ud6c4 \uadf8 \uacb0\uacfc\uc5d0 \uc0c1\uad00\uc5c6\uc774 \uc0ac\uac74 B\ub97c \uc120\ud0dd\ud560 \uc218 \uc788\ub294 \uad6c\uc870\ub77c\uba74 \uc6b0\ub9ac\ub294 \uc804\uccb4 \uacbd\uc6b0\uc758 \uc218\ub97c \uad6c\ud558\uae30 \uc704\ud574 \uacf1\uc148\uc744 \uc218\ud589\ud569\ub2c8\ub2e4. \uc774\ub97c \uc218\ud559\uc801 \uae30\ud638\ub85c \ub098\ud0c0\ub0b4\uba74, \uc0ac\uac74 A\uc758 \uacbd\uc6b0\uc758 \uc218\ub97c $n(A)$, \uc0ac\uac74 B\uc758 \uacbd\uc6b0\uc758 \uc218\ub97c $n(B)$\ub77c \ud560 \ub54c, \ub450 \uc0ac\uac74\uc774 \ub3d9\uc2dc\uc5d0 \uc77c\uc5b4\ub098\ub294 \uacbd\uc6b0\uc758 \uc218\ub294 $$n(A \\\\times B) = n(A) \\\\times n(B)$$\uc640 \uac19\uc774 \ud45c\ud604\ud560 \uc218 \uc788\uc2b5\ub2c8\ub2e4.",   "\uc774\uc81c \uad6c\uccb4\uc801\uc778 \uc608\uc81c\ub97c \ud1b5\ud574 \uacf1\uc758 \ubc95\uce59\uc744 \uc801\uc6a9\ud574 \ubd05\uc2dc\ub2e4. \'\uc0c1\uc758 3\uc885\ub958\uc640 \ud558\uc758 4\uc885\ub958\uac00 \uc788\uc744 \ub54c, \uc0c1\uc758\uc640 \ud558\uc758\ub97c \uac01\uac01 \ud558\ub098\uc529 \uace8\ub77c \uc785\ub294 \uacbd\uc6b0\uc758 \uc218\'\ub97c \uad6c\ud558\ub294 \ubb38\uc81c\uc785\ub2c8\ub2e4. \uc0c1\uc758\ub97c \uace0\ub974\ub294 \uc0ac\uac74\uc744 A, \ud558\uc758\ub97c \uace0\ub974\ub294 \uc0ac\uac74\uc744 B\ub77c\uace0 \ud558\uba74, \uc0c1\uc758\ub97c \uace0\ub974\ub294 \uacbd\uc6b0\uc758 \uc218\ub294 $n(A) = 3$\uc774\uace0, \ud558\uc758\ub97c \uace0\ub974\ub294 \uacbd\uc6b0\uc758 \uc218\ub294 $n(B) = 4$\uc785\ub2c8\ub2e4. \uc0c1\uc758 \ud558\ub098\ub97c \uace0\ub97c \ub54c\ub9c8\ub2e4 4\uac00\uc9c0\uc758 \ud558\uc758\ub97c \uc9dd\uc9c0\uc744 \uc218 \uc788\uc73c\ubbc0\ub85c, \uc804\uccb4 \uacbd\uc6b0\uc758 \uc218\ub294 $$3 \\\\times 4 = 12$$\uac00\uc9c0\uac00 \ub429\ub2c8\ub2e4.",   "\uc870\uae08 \ub354 \ubcf5\uc7a1\ud55c \uc608\uc81c\ub85c, \'\uc11c\ub85c \ub2e4\ub978 \uc8fc\uc0ac\uc704 2\uac1c\ub97c \ub3d9\uc2dc\uc5d0 \ub358\uc9c8 \ub54c \ub098\uc624\ub294 \ub208\uc758 \uc218\uc758 \uacbd\uc6b0\uc758 \uc218\'\ub97c \uc0dd\uac01\ud574 \ubd05\uc2dc\ub2e4. \uccab \ubc88\uc9f8 \uc8fc\uc0ac\uc704\uc5d0\uc11c \ub098\uc62c \uc218 \uc788\ub294 \ub208\uc758 \uc218\ub294 $\\{1, 2, 3, 4, 5, 6\\}$\uc73c\ub85c \ucd1d 6\uac00\uc9c0\uc785\ub2c8\ub2e4. \ub450 \ubc88\uc9f8 \uc8fc\uc0ac\uc704 \uc5ed\uc2dc $\\{1, 2, 3, 4, 5, 6\\}$\uc73c\ub85c \ucd1d 6\uac00\uc9c0\uc785\ub2c8\ub2e4. \uccab \ubc88\uc9f8 \uc8fc\uc0ac\uc704\uc758 \uac01 \ub208\uc5d0 \ub300\ud558\uc5ec \ub450 \ubc88\uc9f8 \uc8fc\uc0ac\uc704\uc758 \ub208\uc774 \uac01\uac01 \ub300\uc751\ub418\ubbc0\ub85c, \uacf1\uc758 \ubc95\uce59\uc5d0 \uc758\ud574 \uc804\uccb4 \uacbd\uc6b0\uc758 \uc218\ub294 $$6 \\\\times 6 = 36$$\uac00\uc9c0\uac00 \ub429\ub2c8\ub2e4.",   "\ub9c8\uc9c0\ub9c9\uc73c\ub85c \uacbd\ub85c\uc758 \uc218\ub97c \uad6c\ud558\ub294 \ubb38\uc81c\uc5d0 \uc801\uc6a9\ud574 \ubcf4\uaca0\uc2b5\ub2c8\ub2e4. \ub3c4\uc2dc A\uc5d0\uc11c \ub3c4\uc2dc B\ub85c \uac00\ub294 \uae38\uc774 2\uac1c \uc788\uace0, \ub3c4\uc2dc B\uc5d0\uc11c \ub3c4\uc2dc C\ub85c \uac00\ub294 \uae38\uc774 3\uac1c \uc788\uc744 \ub54c, A\uc5d0\uc11c B\ub97c \uac70\uccd0 C\ub85c \uac00\ub294 \ubc29\ubc95\uc758 \uc218\ub97c \uad6c\ud574\ubd05\uc2dc\ub2e4. A\uc5d0\uc11c B\ub85c \uac00\ub294 \uc0ac\uac74\uc744 $m=2$, B\uc5d0\uc11c C\ub85c \uac00\ub294 \uc0ac\uac74\uc744 $n=3$\uc774\ub77c\uace0 \ud558\uba74, \uc804\uccb4 \uacbd\ub85c\ub294 A\uc5d0\uc11c B\ub85c \uac00\ub294 \uac01\uac01\uc758 \uae38\ub9c8\ub2e4 B\uc5d0\uc11c C\ub85c \uac00\ub294 3\uac1c\uc758 \uae38\uc774 \uc5f0\uacb0\ub418\uc5b4 \uc788\uc73c\ubbc0\ub85c $$2 \\\\times 3 = 6$$\uac00\uc9c0\uac00 \ub429\ub2c8\ub2e4. \uc774\ucc98\ub7fc \uacf1\uc758 \ubc95\uce59\uc740 \ubcf5\uc7a1\ud55c \uc120\ud0dd\uc758 \uacfc\uc815\uc744 \ub2e8\uc21c\ud654\ud558\uc5ec \uc804\uccb4 \uacbd\uc6b0\ub97c \ube60\uc9d0\uc5c6\uc774 \uc138\ub294 \ub370 \ub9e4\uc6b0 \uc720\uc6a9\ud55c \ub3c4\uad6c\uc785\ub2c8\ub2e4." ]'],ai0),t8,B.n)],ai2),t8,B.n)],ai3),s3,s3,s3,"concept_\uc0ac\uac74\uc758\uacf1",0,"","\uacf5\ud1b5\uc218\ud5591 > \uacbd\uc6b0\uc758\uc218 > \uacf1\uc758\ubc95\uce59 > \uc0ac\uac74\uc758\uacf1",a,t8,s3)
